from pathlib import Path
import base64, subprocess, zlib

PAYLOAD = """"""

patch = zlib.decompress(base64.b64decode(PAYLOAD))
root = Path(__file__).resolve().parent
proc = subprocess.run(["git", "apply", "--check", "-"], input=patch, cwd=root)
if proc.returncode != 0:
    raise SystemExit(proc.returncode)
proc = subprocess.run(["git", "apply", "--whitespace=nowarn", "-"], input=patch, cwd=root)
raise SystemExit(proc.returncode)
